	actions := []axBatchAction{
		{actionType: "click", targetRef: "r1"},
		{actionType: "keypress", key: "DOWN"},
		{actionType: "keypress", key: "ENTER"},
		{actionType: "set_value", targetRef: "r2", value: "6"},
