				t.Fatal(err)
			}
			if r := response.Accessibility; r != nil {
				r.PrepareForService()
				if name == "focus" && r.FocusPreparation != focusPreparationUnknown {
					t.Fatal("lost focus preparation")
				}
				if name == "pointer" && r.PointerPreparation != pointerPreparationUnknown {
