			unknown, _ := json.Marshal(raw)
			if _, err := DecodeProviderWireResponse(unknown); err == nil || !strings.Contains(err.Error(), "unknown field") {
				t.Fatalf("strict decoder accepted unknown native fact: %v", err)
			}
